tool.command:
#import os #set $staged_inputs = [$xyz] #if $extra_files #set $staged_inputs = $staged_inputs + list($extra_files) #end if
. /etc/profile && module load PrgEnv-cray && module load craype-accel-amd-gfx90a && module load cray-fftw && module load cpe && module load rocm &&
mkdir -p lammps_outputs &&
ln -s $lmp input.lmp &&
#for $f in $staged_inputs #set $staged_name = os.path.basename(str($f.element_identifier)) test ! -e 'lammps_outputs/$staged_name' || { echo 'ERROR: more than one input file is named $staged_name' >&2 ; exit 1 ; } && cp '$f' 'lammps_outputs/$staged_name' && #end for
export INSTDIR="/lustre/orion/bip280/proj-shared/LAMMPS_Stable_KOKKOSwfcut/lammps/install/bin" && export OMP_NUM_THREADS=1 && export MPICH_GPU_SUPPORT_ENABLED=1 &&
( cd lammps_outputs && \${INSTDIR}/lmp_frontier -k on g 1 -sf kk -pk kokkos -in ../input.lmp ) > >(tee -a $output) 2> >(tee -a $output >&2) ;
lammps_exit=\$? ;
#for $f in $staged_inputs #set $staged_name = os.path.basename(str($f.element_identifier)) if cmp -s '$f' 'lammps_outputs/$staged_name' ; then rm -f 'lammps_outputs/$staged_name' ; fi ; #end for
exit \${lammps_exit}
